def solution(meetings):
    # The peak overlap happens at some meeting's start: count the meetings
    # running at each start. O(n^2).
    best = 0
    for s, _ in meetings:
        running = 0
        for a, b in meetings:
            if a <= s < b:
                running += 1
        best = max(best, running)
    return best
